using System.Collections.ObjectModel;
using System.ComponentModel;
using System.Runtime.CompilerServices;
using System.Windows.Input;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Maui;
using Microsoft.Maui.Controls;

namespace MAUIDemo
{
    // === Model ===
    public class Product
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public decimal Price { get; set; }
    }

    // === MVVM 基础设施 ===
    public class ObservableObject : INotifyPropertyChanged
    {
        public event PropertyChangedEventHandler PropertyChanged;

        protected void OnPropertyChanged([CallerMemberName] string name = null)
            => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));

        protected bool Set<T>(ref T field, T value, [CallerMemberName] string name = null)
        {
            if (EqualityComparer<T>.Default.Equals(field, value)) return false;
            field = value;
            OnPropertyChanged(name);
            return true;
        }
    }

    public class AsyncCommand : ICommand
    {
        private readonly Func<Task> _execute;
        private bool _busy;

        public AsyncCommand(Func<Task> execute) => _execute = execute;

        public event EventHandler CanExecuteChanged;
        public bool CanExecute(object _) => !_busy;

        public async void Execute(object _)
        {
            if (_busy) return;
            _busy = true;
            CanExecuteChanged?.Invoke(this, EventArgs.Empty);
            try { await _execute(); }
            finally { _busy = false; CanExecuteChanged?.Invoke(this, EventArgs.Empty); }
        }
    }

    // === ViewModel ===
    public class MainViewModel : ObservableObject
    {
        private readonly IProductService _svc;
        private bool _isBusy;

        public MainViewModel(IProductService svc)
        {
            _svc = svc;
            Products = new ObservableCollection<Product>();
            LoadCmd = new AsyncCommand(LoadAsync);
        }

        public ObservableCollection<Product> Products { get; }
        public bool IsBusy { get => _isBusy; set => Set(ref _isBusy, value); }
        public ICommand LoadCmd { get; }

        private async Task LoadAsync()
        {
            IsBusy = true;
            try
            {
                Products.Clear();
                foreach (var p in await _svc.GetProductsAsync())
                    Products.Add(p);
            }
            finally { IsBusy = false; }
        }
    }

    public class DetailViewModel : ObservableObject, IQueryAttributable
    {
        private readonly IProductService _svc;
        private Product _product;

        public DetailViewModel(IProductService svc) => _svc = svc;
        public Product Product { get => _product; set => Set(ref _product, value); }

        // Shell 路由参数注入
        public void ApplyQueryAttributes(IDictionary<string, object> query)
        {
            if (query.TryGetValue("id", out var id))
                _ = LoadAsync(int.Parse(id.ToString()));
        }

        private async Task LoadAsync(int id) => Product = await _svc.GetByIdAsync(id);
    }

    // === Service 层 ===
    public interface IProductService
    {
        Task<IEnumerable<Product>> GetProductsAsync();
        Task<Product> GetByIdAsync(int id);
    }

    public class ProductService : IProductService
    {
        private readonly HttpClient _http;
        public ProductService(HttpClient http) => _http = http;
        public async Task<IEnumerable<Product>> GetProductsAsync()
            => await _http.GetFromJsonAsync<IEnumerable<Product>>("/api/products");
        public async Task<Product> GetByIdAsync(int id)
            => await _http.GetFromJsonAsync<Product>($"/api/products/{id}");
    }

    // === 平台服务：接口 + 条件编译注册 ===
    public interface IPlatformService
    {
        string PlatformName { get; }
        Task<bool> RequestCameraAsync();
    }

#if ANDROID
    public class AndroidPlatformService : IPlatformService
    {
        public string PlatformName => "Android";
        public async Task<bool> RequestCameraAsync()
        {
            var s = await Permissions.CheckStatusAsync<Permissions.Camera>();
            if (s != PermissionStatus.Granted) s = await Permissions.RequestAsync<Permissions.Camera>();
            return s == PermissionStatus.Granted;
        }
    }
#elif IOS
    public class iOSPlatformService : IPlatformService
    {
        public string PlatformName => "iOS";
        public async Task<bool> RequestCameraAsync()
        {
            var s = await Permissions.CheckStatusAsync<Permissions.Camera>();
            if (s != PermissionStatus.Granted) s = await Permissions.RequestAsync<Permissions.Camera>();
            return s == PermissionStatus.Granted;
        }
    }
#else
    public class DefaultPlatformService : IPlatformService
    {
        public string PlatformName => "Desktop";
        public Task<bool> RequestCameraAsync() => Task.FromResult(false);
    }
#endif

    // === 入口配置 ===
    public static class MauiProgram
    {
        public static MauiApp CreateMauiApp()
        {
            var builder = MauiApp.CreateBuilder();
            builder.UseMauiApp<App>()
                   .ConfigureFonts(f => f.AddFont("OpenSans-Regular.ttf", "OpenSansRegular"));

            // HTTP + 业务服务
            builder.Services.AddHttpClient<IProductService, ProductService>(
                c => c.BaseAddress = new Uri("https://api.example.com"));

            // 平台服务：条件编译注册
            builder.Services.AddSingleton<IPlatformService>(p =>
            {
#if ANDROID
                return new AndroidPlatformService();
#elif IOS
                return new iOSPlatformService();
#else
                return new DefaultPlatformService();
#endif
            });

            // 页面和 ViewModel
            builder.Services.AddTransient<MainPage>();
            builder.Services.AddTransient<MainViewModel>();
            builder.Services.AddTransient<DetailPage>();
            builder.Services.AddTransient<DetailViewModel>();

            return builder.Build();
        }
    }

    // === Shell 路由注册 ===
    public partial class App : Application
    {
        public App()
        {
            InitializeComponent();
            Routing.RegisterRoute("detail", typeof(DetailPage));
            MainPage = new AppShell();
        }
    }
}
